const FDukeCharacterDef* UDukeGameInstance::FindCharacter(const FString& Id) const
{
	return Characters.FindByPredicate([&](const FDukeCharacterDef& C) { return C.Id == Id; });
}
const FDukeCharacterDef* UDukeGameInstance::Protagonist() const
{
	const FDukeCharacterDef* P = Characters.FindByPredicate([](const FDukeCharacterDef& C) { return C.Role == TEXT("Protagonist"); });
	return P ? P : (Characters.Num() ? &Characters[0] : nullptr);
}
const FDukeDistrictDef* UDukeGameInstance::FindDistrict(const FString& Id) const
{
	return Districts.FindByPredicate([&](const FDukeDistrictDef& D) { return D.Id == Id; });
}
FString UDukeGameInstance::DistrictNameAt(const FVector& P) const
{
	const int32 I = FMath::Clamp(FMath::FloorToInt(P.X / (BlockSize * 100.f)), 0, GridN - 1);
	const int32 J = FMath::Clamp(FMath::FloorToInt(P.Y / (BlockSize * 100.f)), 0, GridN - 1);
	const int32 K = J * GridN + I;
	if (Zone.IsValidIndex(K) && Districts.IsValidIndex(Zone[K])) return Districts[Zone[K]].Name;
	return CityName;
}
